mapper.select:
select id, pool_name, merchant_member_id, entry_node_id, topic_id, status, create_by, create_time, update_time
from node_task_pool

     and pool_name like concat('%', #{poolName}, '%') 
     and merchant_member_id = #{merchantMemberId} 
     and entry_node_id = #{entryNodeId} 
     and topic_id = #{topicId} 
     and status = #{status} 

order by id desc

mapper.update:
update node_task_pool
pool_name = #{poolName}, merchant_member_id = #{merchantMemberId}, entry_node_id = #{entryNodeId}, topic_id = #{topicId}, status = #{status}, update_time = now()
where id = #{id}

update node_task_pool_item
node_id = #{nodeId}, weight = #{weight}, status = #{status},
where id = #{id}

mapper.select:
select id, member_id, pool_id, date_format(dispatch_date, '%Y-%m-%d') as dispatch_date, node_id, random_receipt_id, created_at
from node_task_dispatch
where member_id = #{memberId}
  and pool_id = #{poolId}
  and dispatch_date = #{dispatchDate}
limit 1

select id, member_id, pool_id, date_format(dispatch_date, '%Y-%m-%d') as dispatch_date, node_id, random_receipt_id, created_at
from node_task_dispatch
where member_id = #{memberId}
  and pool_id = #{poolId}
  and dispatch_date < #{dispatchDate}
order by dispatch_date desc, id desc
limit 1

select id, member_id, pool_id, date_format(dispatch_date, '%Y-%m-%d') as dispatch_date, node_id, random_receipt_id, created_at
from node_task_dispatch

     and member_id = #{memberId} 
     and pool_id = #{poolId} 
     and dispatch_date = #{dispatchDate} 
     and node_id = #{nodeId} 

order by id desc
limit 200
